<script lang="ts">
  import { client, site } from '$lib/api/client.svelte'
  import { PiefedClient } from '$lib/api/piefed/adapter'
  import type { PostView } from '$lib/api/types'
  import { profile } from '$lib/app/auth'
  import { errorMessage } from '$lib/app/error'

  import MarkdownEditor from '$lib/app/markdown/MarkdownEditor.svelte'
  import { settings } from '$lib/app/settings.svelte'
  import { placeholders } from '$lib/app/util.svelte'
  import Duration from '$lib/ui/form/Duration.svelte'
  import FreeTextInput from '$lib/ui/form/FreeTextInput.svelte'
  import ImageInputModal from '$lib/ui/form/ImageInputModal.svelte'
  import ObjectAutocomplete from '$lib/ui/form/ObjectAutocomplete.svelte'
  import MultiSelect from '$lib/ui/form/Switch.svelte'
  import Avatar from '$lib/ui/generic/Avatar.svelte'
  import ErrorContainer, { pushError } from '$lib/ui/info/ErrorContainer.svelte'
  import { CommonList, Header } from '$lib/ui/layout'
  import EndPlaceholder from '$lib/ui/layout/EndPlaceholder.svelte'
  import { publishedToDate } from '$lib/ui/util/date'
  import {
    Badge,
    Button,
    ButtonGroup,
    Label,
    Material,
    modal,
    Option,
    Select,
    Spinner,
    Switch,
    TextArea,
    TextInput,
    TextLoader,
  } from 'mono-svelte'
  import type { Snippet } from 'svelte'
  import {
    ChatBubbleBottomCenterText,
    Check,
    Icon,
    Language,
    Photo,
    Plus,
    QrCode,
    Sparkles,
    Tag,
    Trash,
    XMark,
  } from 'svelte-hero-icons/dist'
  import { autofillPost, PostFormState } from './postform.svelte'
  import ImageUploader from '$lib/feature/media/ImageUploader.svelte'
  import MediaDisplay from '$lib/feature/media/MediaDisplay.svelte'
  import type { Media } from '$lib/api/threadlight/types'

  interface Props {
    editPost?: number
    init?: PostFormState
    title?: Snippet
    onsubmit?: (post: PostView) => void
  }

  let { editPost, init, title, onsubmit }: Props = $props()

  let form = $state<PostFormState>(
    init ?? new PostFormState({ type: 'normal' }),
  )

  let extendedCommunity = $derived.by(() => {
    const api = client()
    if (!(api instanceof PiefedClient)) return undefined

    if (form.community?.id) {
      return api.getCommunity({ id: form.community.id })
    } else return undefined
  })

  let loading = $state<boolean>(false)
  let uploadImage = $state(false)
  let customThumbnail = $state(false)
  let showImageUploader = $state(false)
  let uploadedMedia = $state<Media | null>(null)

  function handleImageUpload(media: Media) {
    uploadedMedia = media
    form.mediaId = media.id
    showImageUploader = false
  }

  function removeUploadedImage() {
    uploadedMedia = null
    form.mediaId = undefined
  }

  async function autofill(
    data: URL | { title?: string; body?: string },
  ): Promise<{ title?: string; body?: string }> {
    if (data instanceof URL) {
      const res = await autofillPost(data)

      if (settings.forms.autosubmitAutofill) {
        autofill({
          title: res.title,
          body: res.body,
        })
        history?.back?.()
      }

      return res
    } else {
      form.title = data.title || form.title
      form.body =
        data.body
          ?.split('\n')
          .map((i) => `> ${i}`)
          .join('\n') || form.body

      return {
        title: form.title,
        body: form.body,
      }
    }
  }
</script>

{#if profile.client instanceof PiefedClient && !editPost}
  <div class="mb-3">
    <MultiSelect
      options={['normal', 'poll']}
      optionNames={['Discussion','Poll','Event',
      ]}
      bind:selected={form.type}
    />
  </div>
{/if}

{#if uploadImage}
  <ImageInputModal
    bind:open={uploadImage}
    bind:imageUrl={() => '', (v) => (form.url = v)}
  />
{/if}

{#if customThumbnail}
  <ImageInputModal
    bind:open={customThumbnail}
    bind:imageUrl={() => form.thumbnail, (v) => (form.thumbnail = v)}
  />
{/if}

{#snippet altText()}
  <TextArea bind:value={form.altText} />
{/snippet}

{#snippet flairs()}
  <Material color="uniform" class="flex flex-row gap-4 flex-wrap">
    {#await extendedCommunity}
      <div class="w-full h-full grid place-items-center">
        <Spinner />
      </div>
    {:then communityView}
      {#each communityView?.community_view.flair_list ?? [] as flair}
        {@const selected = form.flairList?.some((i) => i.id == flair.id)}
        <button
          class="rounded-full cursor-pointer hover:brightness-100 badge-tag-color"
          style="--tag-color: {flair.background_color}; --tag-text-color: {flair.text_color};"
          onclick={() => {
            if (selected) {
              const index = form.flairList.findIndex((i) => i.id == flair.id)
              if (index != -1) form.flairList.splice(index, 1)
            } else form.flairList.push(flair)
          }}
        >
          <Badge
            color={selected ? 'gray-subtle' : 'custom'}
            class="ring-white/20"
          >
            {#snippet icon()}
              <Icon src={selected ? Check : Plus} size="16" micro />
            {/snippet}
            {flair.flair_title}
          </Badge>
        </button>
      {/each}
    {/await}
  </Material>
{/snippet}

{#snippet autofillPostModal()}
  <svelte:boundary>
    {#if form.url}
      {#key form.url}
        {#await autofill(new URL(form.url))}
          <div class="w-full h-48 grid place-items-center">
            <TextLoader>
              Fetching site metadata
            </TextLoader>
          </div>
          <Button size="lg" color="secondary" onclick={history.back}>
            Cancel
          </Button>
        {:then url}
          {#if !url}
            <!--cursed svelte template abuse. don't do this lads-->
            {history.back()}
          {/if}
          <Material color="info" class="space-y-2 h-48">
            <h2 class="text-xl font-display font-medium">{url.title}</h2>
            <p class="overflow-hidden text-ellipsis">{url.body ?? '...'}</p>
          </Material>
          <Button
            size="lg"
            color="primary"
            onclick={() => {
              autofill({ title: url.title, body: url.body })
              history.back()
            }}
          >
            Submit
          </Button>
        {:catch err}
          <ErrorContainer scope="-1" message={err} />
        {/await}
        <Switch class="mt-4" bind:checked={settings.forms.autosubmitAutofill}>
          Submit automatically
        </Switch>
      {/key}
    {/if}
  </svelte:boundary>
{/snippet}

<form
  onsubmit={(e) => {
    e.preventDefault()
    loading = true

    form
      .submit(editPost)
      .then(onsubmit)
      .catch((err) =>
        pushError({ message: errorMessage(err as string), scope: 'post-form' }),
      )
      .then(() => (loading = false))
  }}
  class="flex flex-col gap-4 h-full"
>
  {#if title}
    {@render title()}
  {:else}
    <Header class="font-bold text-xl">
      {editPost ?'Edit post' :'Create post'}
    </Header>
  {/if}
  <ErrorContainer scope="post-form" />
  {#if !editPost}
    {#if !form.community}
      <ObjectAutocomplete
        listing_type="All"
        label=Community
        onselect={(i) => {
          form.community = i.community
        }}
        required
      />
    {:else}
      <div class="flex flex-col gap-1">
        <Label>Community</Label>
        <Button
          class="w-full"
          onclick={() => (form.community = undefined)}
          alignment="left"
          size="sm"
          rounding="xl"
        >
          {#snippet prefix()}
            <Avatar
              url={form.community?.icon}
              alt={form.community?.name}
              width={24}
            />
          {/snippet}
          <div class="flex flex-col gap-0">
            <span class="text-sm">{form.community.name}</span>
            <span class="text-[10px] leading-3">
              {new URL(form.community?.actor_id).hostname}
            </span>
          </div>
        </Button>
      </div>
    {/if}
  {/if}

  <FreeTextInput
    required
    bind:value={form.title}
    placeholder={placeholders.get('post')}
    label=Title
    class="font-display font-medium text-2xl"
  />
  <MarkdownEditor
    label=Body
    bind:value={form.body}
    placeholder={placeholders.get('body')}
    previewButton
  />

  <!-- Image upload section -->
  {#if showImageUploader}
    <div class="rounded-xl border border-slate-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 p-4">
      <div class="flex items-center justify-between mb-2">
        <h3 class="font-semibold text-sm">Upload Image</h3>
        <Button
          size="xs"
          rounding="xl"
          onclick={() => (showImageUploader = false)}
          icon={XMark}
        >
          Cancel
        </Button>
      </div>
      <ImageUploader onUpload={handleImageUpload} maxSizeMB={10} />
    </div>
  {:else if uploadedMedia}
    <div class="rounded-xl border border-slate-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 p-4 space-y-2">
      <div class="flex items-center justify-between">
        <h3 class="font-semibold text-sm">Attached Image</h3>
        <Button
          size="xs"
          rounding="xl"
          color="danger"
          onclick={removeUploadedImage}
          icon={Trash}
        >
          Remove
        </Button>
      </div>
      <MediaDisplay
        src={uploadedMedia.file_path}
        alt={uploadedMedia.original_name ?? ''}
        maxWidth={400}
      />
      <div class="text-xs text-zinc-500">
        {uploadedMedia.original_name ?? 'Image'} &middot; {uploadedMedia.width}&times;{uploadedMedia.height}
      </div>
    </div>
  {/if}

  {#if form.type == 'normal'}
    <TextInput
      label=URL
      bind:value={form.url}
      placeholder={placeholders.get('url')}
    >
      {#snippet suffix()}
        <Button
          color="none"
          rounding="none"
          class="h-full border-l border-slate-200 dark:border-zinc-800 aspect-square hover:bg-slate-50 hover:dark:bg-zinc-900 rounded-[inherit]"
          size="custom"
          disabled={!form.url || !URL.canParse(form.url)}
          icon={Sparkles}
          aria-label=Autofill post
          onclick={() =>
            modal({
              title:'Autofill post',
              snippet: autofillPostModal,
              actions: [],
            })}
        />
      {/snippet}
    </TextInput>
  {/if}

  {#if form.type == 'poll' && form.poll}
    <div>
      <Label>Choices</Label>
      <CommonList>
        <!--eslint-disable-next-line @typescript-eslint/no-unused-vars-->
        {#each form.poll.choices as _, index}
          <li class="px-4 py-1 flex flex-row items-center xs">
            <div class="p-0! font-medium flex-1">
              <FreeTextInput
                bind:value={form.poll.choices[index].choice_text}
                class="w-full"
              />
            </div>
            <div>
              <Button
                onclick={() => form.poll?.choices.splice(index, 1)}
                size="square-md"
                aria-label=Delete
              >
                <Icon src={Trash} size="16" mini />
              </Button>
            </div>
          </li>
        {/each}
        <li class="xs">
          <button
            onclick={() =>
              form.poll?.choices.push({
                choice_text: `Option ${form.poll?.choices.length + 1}`,
                id: Math.max(...form.poll.choices.map((i) => i.id)) + 1,
                num_votes: 0,
                sort_order: 2,
              })}
            type="button"
            class="font-medium w-full px-4 py-2! flex flex-row items-center gap-1 justify-center cursor-pointer"
          >
            <Icon src={Plus} size="16" micro />
            Add
          </button>
        </li>
      </CommonList>
    </div>

    <EndPlaceholder margin="bottom-lg">
      <Select label=Mode bind:value={form.poll!.mode}>
        <Option value="single">
          Single choice
        </Option>
        <Option value="multiple">
          Multiple choice
        </Option>
      </Select>
      {#snippet action()}
        {#if !editPost}
          <Duration
            bind:value={
              () => {
                return form.poll?.end_poll
                  ? Math.floor(
                      Date.now() -
                        publishedToDate(form.poll?.end_poll).getTime(),
                    )
                  : Date.now() + 24 * 60 * 60
              },
              (v) => {
                if (v <= 0) form.poll!.end_poll = undefined
                else
                  form.poll!.end_poll = new Date(
                    Date.now() + v * 1000,
                  ).toISOString()
              }
            }
          />
        {/if}
      {/snippet}
    </EndPlaceholder>

    {#if settings.debugInfo}
      {form.poll?.end_poll}
    {/if}
  {/if}

  <div class="flex flex-row overflow-auto gap-2 -mx-3 px-3 relative">
    <div
      class="bg-gradient-to-r from-slate-25 to-slate-25/0 dark:from-zinc-925 dark:to-zinc-925/0 absolute left-0 w-3 h-full z-10"
    ></div>
    <div
      class="bg-gradient-to-l from-slate-25 to-slate-25/0 dark:from-zinc-925 dark:to-zinc-925/0 absolute right-0 w-3 h-full z-10"
    ></div>
    <ButtonGroup
      orientation="horizontal"
      class="flex flex-row *:flex-shrink-0 w-full"
    >
      {#if form.type == 'normal'}
        <Button
          onclick={() => {
            uploadImage = !uploadImage
          }}
          icon={Photo}
        >
          Upload image
        </Button>
        <Button
          onclick={() => {
            showImageUploader = !showImageUploader
          }}
          color={uploadedMedia ? 'primary' : 'secondary'}
          icon={Photo}
        >
          {uploadedMedia ? 'Image attached' : 'Add image'}
        </Button>
        {#if form.url && URL.canParse(form.url)}
          <Button
            class="animate-pop-in"
            color={(form.altText ?? '') != '' ? 'primary' : 'secondary'}
            onclick={() =>
              modal({ title:'Alt text', snippet: altText })}
            icon={ChatBubbleBottomCenterText}
          >
            Alt text
          </Button>
        {/if}
        {#if form.url}
          <Button
            class="animate-pop-in"
            onclick={() => {
              customThumbnail = !customThumbnail
            }}
            color={form.thumbnail ? 'primary' : 'secondary'}
            icon={QrCode}
          >
            Set thumbnail
          </Button>
        {/if}
      {/if}
      {#if form.language === undefined}
        <Button onclick={() => (form.language = '')} icon={Language}>
          Set language
        </Button>
      {/if}
      {#await extendedCommunity then communityView}
        {#if (communityView?.community_view.flair_list?.length || 0) > 0}
          <Button
            color={form.flairList.length > 0 ? 'primary' : 'secondary'}
            class="animate-pop-in"
            onclick={() =>
              modal({ title:'Add flair', snippet: flairs })}
            icon={Tag}
          >
            Add flair
          </Button>
        {/if}
      {/await}
    </ButtonGroup>
  </div>

  {#if form.language !== undefined}
    {#if site.data}
      <Select
        class="w-max"
        label=Language
        bind:value={
          () => form.language,
          (v) => {
            if (v == '') form.language = undefined
            else form.language = v
          }
        }
      >
        <Option value="">
          <Icon src={XMark} size="16" micro />
          Unset
        </Option>
        {#each site.data?.all_languages as language}
          <Option value={language.id.toString()}>{language.name}</Option>
        {/each}
      </Select>
    {:else}
      <div style="height: 58px;">
        <Spinner width={24} />
      </div>
    {/if}
  {/if}

  <Switch bind:checked={form.nsfw}>NSFW</Switch>

  <Button submit color="primary" {loading} size="lg" class="mt-auto">
    Submit
  </Button>
</form>
